  ('cf37e43b-981d-44bb-84c7-34f848ff01f5', '332409ec-c891-4a5e-8fe9-ee83edcfb895', null, 'topic'::public.curated_course_node_type, 'System Architecture and the Biomedical Measurement Chain', 'This opening unit gives students the map of a biomedical instrument from patient interface to clinical display. The point is to see every later circuit, sensor, filter, and software choice as part of one measurement chain whose output affects patient care.', 0),
  ('5e730bf0-4a1d-4f85-9187-f6d64bfc4a0f', '332409ec-c891-4a5e-8fe9-ee83edcfb895', 'cf37e43b-981d-44bb-84c7-34f848ff01f5', 'subtopic'::public.curated_course_node_type, 'Measurement-chain blocks', 'Students learn how measurand, sensor, analog front end, converter, processor, storage, display, and user workflow fit together.', 0),
