  ('7c3a0175-195c-4c7c-9d80-c0c164cf7669', '332409ec-c891-4a5e-8fe9-ee83edcfb895', null, 'topic'::public.curated_course_node_type, 'Bioelectric Signals and Electrode Interfaces', 'Bioelectric measurements are central to ECG, EEG, EMG, and many bedside monitors. This topic explains where those signals come from and why the electrode-skin interface is often the hardest part of the system.', 1),
  ('c3bce34c-0e75-4d8c-964e-42e81a13ea6b', '332409ec-c891-4a5e-8fe9-ee83edcfb895', '7c3a0175-195c-4c7c-9d80-c0c164cf7669', 'subtopic'::public.curated_course_node_type, 'Physiological origins of biopotentials', 'Students connect cellular activity to measurable body-surface voltage patterns.', 0),
