  ('37211d90-29de-4676-81f7-1b29ae7a5c96', '332409ec-c891-4a5e-8fe9-ee83edcfb895', null, 'topic'::public.curated_course_node_type, 'Transducers, Sensors, and Signal Conditioning', 'Biomedical instrumentation starts with converting physiological phenomena into electrical information. This section builds fluency with sensor families and the first conditioning circuits that make weak biological signals usable.', 2),
  ('18f38625-872e-4899-9cab-be2f0eb73bc8', '332409ec-c891-4a5e-8fe9-ee83edcfb895', '37211d90-29de-4676-81f7-1b29ae7a5c96', 'subtopic'::public.curated_course_node_type, 'Sensor principles', 'Students compare how common transducers convert pressure, flow, displacement, temperature, light, and chemical concentration into voltage, current, resistance, capacitance, or frequency.', 0),
